1	package v1
2	
3	import (
4		"context"
5		"fmt"
6		"strings"
7	
8		"github.com/pkg/errors"
9		"google.golang.org/grpc/codes"
10		"google.golang.org/grpc/status"
11		"google.golang.org/protobuf/types/known/emptypb"
12	
13		"github.com/usememos/memos/internal/filter"
14		"github.com/usememos/memos/internal/util"
15		v1pb "github.com/usememos/memos/proto/gen/api/v1"
16		storepb "github.com/usememos/memos/proto/gen/store"
17		"github.com/usememos/memos/store"
18	)
19	
20	// Helper function to extract user and shortcut ID from shortcut resource name.
21	// Format: users/{user}/shortcuts/{shortcut}.
22	func (s *APIV1Service) extractUserAndShortcutIDFromName(ctx context.Context, name string) (*store.User, string, error) {
23		parts := strings.Split(name, "/")
24		if len(parts) != 4 || parts[0] != "users" || parts[2] != "shortcuts" {
25			return nil, "", errors.Errorf("invalid shortcut name format: %s", name)
26		}
27	
28		user, err := ResolveUserByName(ctx, s.Store, BuildUserName(parts[1]))
29		if err != nil {
30			return nil, "", err
31		}
32		if user == nil {
33			return nil, "", errors.Errorf("user not found: %s", parts[1])
34		}
35	
36		shortcutID := parts[3]
37		if shortcutID == "" {
38			return nil, "", errors.Errorf("empty shortcut ID in name: %s", name)
39		}
40	
41		return user, shortcutID, nil
42	}
43	
44	// Helper function to construct shortcut resource name.
45	func constructShortcutName(username string, shortcutID string) string {
46		return fmt.Sprintf("%s/shortcuts/%s", BuildUserName(username), shortcutID)
47	}
48	
49	func (s *APIV1Service) ListShortcuts(ctx context.Context, request *v1pb.ListShortcutsRequest) (*v1pb.ListShortcutsResponse, error) {
50		user, err := ResolveUserByName(ctx, s.Store, request.Parent)
51		if err != nil {
52			return nil, status.Errorf(codes.InvalidArgument, "invalid user name: %v", err)
53		}
54		if user == nil {
55			return nil, status.Errorf(codes.NotFound, "user not found")
56		}
57		userID := user.ID
58	
59		currentUser, err := s.fetchCurrentUser(ctx)
60		if err != nil {
61			return nil, status.Errorf(codes.Internal, "failed to get current user: %v", err)
62		}
63		if currentUser == nil || currentUser.ID != userID {
64			return nil, status.Errorf(codes.PermissionDenied, "permission denied")
65		}
66	
67		userSetting, err := s.Store.GetUserSetting(ctx, &store.FindUserSetting{
68			UserID: &userID,
69			Key:    storepb.UserSetting_SHORTCUTS,
70		})
71		if err != nil {
72			return nil, status.Errorf(codes.Internal, "failed to get user setting: %v", err)
73		}
74		if userSetting == nil {
75			return &v1pb.ListShortcutsResponse{
76				Shortcuts: []*v1pb.Shortcut{},
77			}, nil
78		}
79	
80		shortcutsUserSetting := userSetting.GetShortcuts()
81		shortcuts := []*v1pb.Shortcut{}
82		for _, shortcut := range shortcutsUserSetting.GetShortcuts() {
83			shortcuts = append(shortcuts, &v1pb.Shortcut{
84				Name:   constructShortcutName(user.Username, shortcut.GetId()),
85				Title:  shortcut.GetTitle(),
86				Filter: shortcut.GetFilter(),
87			})
88		}
89	
90		return &v1pb.ListShortcutsResponse{
91			Shortcuts: shortcuts,
92		}, nil
93	}
94	
95	func (s *APIV1Service) GetShortcut(ctx context.Context, request *v1pb.GetShortcutRequest) (*v1pb.Shortcut, error) {
96		user, shortcutID, err := s.extractUserAndShortcutIDFromName(ctx, request.Name)
97		if err != nil {
98			return nil, status.Errorf(codes.InvalidArgument, "invalid shortcut name: %v", err)
99		}
100		userID := user.ID
101	
102		currentUser, err := s.fetchCurrentUser(ctx)
103		if err != nil {
104			return nil, status.Errorf(codes.Internal, "failed to get current user: %v", err)
105		}
106		if currentUser == nil || currentUser.ID != userID {
107			return nil, status.Errorf(codes.PermissionDenied, "permission denied")
108		}
109	
110		userSetting, err := s.Store.GetUserSetting(ctx, &store.FindUserSetting{
111			UserID: &userID,
112			Key:    storepb.UserSetting_SHORTCUTS,
113		})
114		if err != nil {
115			return nil, err
116		}
117		if userSetting == nil {
118			return nil, status.Errorf(codes.NotFound, "shortcut not found")
119		}
120	
121		shortcutsUserSetting := userSetting.GetShortcuts()
122		for _, shortcut := range shortcutsUserSetting.GetShortcuts() {
123			if shortcut.GetId() == shortcutID {
124				return &v1pb.Shortcut{
125					Name:   constructShortcutName(user.Username, shortcut.GetId()),
126					Title:  shortcut.GetTitle(),
127					Filter: shortcut.GetFilter(),
128				}, nil
129			}
130		}
131	
132		return nil, status.Errorf(codes.NotFound, "shortcut not found")
133	}
134	
135	func (s *APIV1Service) CreateShortcut(ctx context.Context, request *v1pb.CreateShortcutRequest) (*v1pb.Shortcut, error) {
136		user, err := ResolveUserByName(ctx, s.Store, request.Parent)
137		if err != nil {
138			return nil, status.Errorf(codes.InvalidArgument, "invalid user name: %v", err)
139		}
140		if user == nil {
141			return nil, status.Errorf(codes.NotFound, "user not found")
142		}
143		userID := user.ID
144	
145		currentUser, err := s.fetchCurrentUser(ctx)
146		if err != nil {
147			return nil, status.Errorf(codes.Internal, "failed to get current user: %v", err)
148		}
149		if currentUser == nil || currentUser.ID != userID {
150			return nil, status.Errorf(codes.PermissionDenied, "permission denied")
151		}
152	
153		newShortcut := &storepb.ShortcutsUserSetting_Shortcut{
154			Id:     util.GenUUID(),
155			Title:  request.Shortcut.GetTitle(),
156			Filter: request.Shortcut.GetFilter(),
157		}
158		if newShortcut.Title == "" {
159			return nil, status.Errorf(codes.InvalidArgument, "title is required")
160		}
161		if err := s.validateFilter(ctx, newShortcut.Filter); err != nil {
162			return nil, status.Errorf(codes.InvalidArgument, "invalid filter: %v", err)
163		}
164		if request.ValidateOnly {
165			return &v1pb.Shortcut{
166				Name:   constructShortcutName(user.Username, newShortcut.GetId()),
167				Title:  newShortcut.GetTitle(),
168				Filter: newShortcut.GetFilter(),
169			}, nil
170		}
171	
172		userSetting, err := s.Store.GetUserSetting(ctx, &store.FindUserSetting{
173			UserID: &userID,
174			Key:    storepb.UserSetting_SHORTCUTS,
175		})
176		if err != nil {
177			return nil, err
178		}
179		if userSetting == nil {
180			userSetting = &storepb.UserSetting{
181				UserId: userID,
182				Key:    storepb.UserSetting_SHORTCUTS,
183				Value: &storepb.UserSetting_Shortcuts{
184					Shortcuts: &storepb.ShortcutsUserSetting{
185						Shortcuts: []*storepb.ShortcutsUserSetting_Shortcut{},
186					},
187				},
188			}
189		}
190		shortcutsUserSetting := userSetting.GetShortcuts()
191		shortcuts := shortcutsUserSetting.GetShortcuts()
192		shortcuts = append(shortcuts, newShortcut)
193		shortcutsUserSetting.Shortcuts = shortcuts
194	
195		userSetting.Value = &storepb.UserSetting_Shortcuts{
196			Shortcuts: shortcutsUserSetting,
197		}
198	
199		_, err = s.Store.UpsertUserSetting(ctx, userSetting)
200		if err != nil {
201			return nil, status.Errorf(codes.Internal, "failed to upsert user setting: %v", err)
202		}
203	
204		return &v1pb.Shortcut{
205			Name:   constructShortcutName(user.Username, newShortcut.GetId()),
206			Title:  newShortcut.GetTitle(),
207			Filter: newShortcut.GetFilter(),
208		}, nil
209	}
210	
211	func (s *APIV1Service) UpdateShortcut(ctx context.Context, request *v1pb.UpdateShortcutRequest) (*v1pb.Shortcut, error) {
212		user, shortcutID, err := s.extractUserAndShortcutIDFromName(ctx, request.Shortcut.Name)
213		if err != nil {
214			return nil, status.Errorf(codes.InvalidArgument, "invalid shortcut name: %v", err)
215		}
216		userID := user.ID
217	
218		currentUser, err := s.fetchCurrentUser(ctx)
219		if err != nil {
220			return nil, status.Errorf(codes.Internal, "failed to get current user: %v", err)
221		}
222		if currentUser == nil || currentUser.ID != userID {
223			return nil, status.Errorf(codes.PermissionDenied, "permission denied")
224		}
225		if request.UpdateMask == nil || len(request.UpdateMask.Paths) == 0 {
226			return nil, status.Errorf(codes.InvalidArgument, "update mask is required")
227		}
228	
229		userSetting, err := s.Store.GetUserSetting(ctx, &store.FindUserSetting{
230			UserID: &userID,
231			Key:    storepb.UserSetting_SHORTCUTS,
232		})
233		if err != nil {
234			return nil, err
235		}
236		if userSetting == nil {
237			return nil, status.Errorf(codes.NotFound, "shortcut not found")
238		}
239	
240		shortcutsUserSetting := userSetting.GetShortcuts()
241		shortcuts := shortcutsUserSetting.GetShortcuts()
242		var foundShortcut *storepb.ShortcutsUserSetting_Shortcut
243		newShortcuts := make([]*storepb.ShortcutsUserSetting_Shortcut, 0, len(shortcuts))
244		for _, shortcut := range shortcuts {
245			if shortcut.GetId() == shortcutID {
246				foundShortcut = shortcut
247				for _, field := range request.UpdateMask.Paths {
248					if field == "title" {
249						if request.Shortcut.GetTitle() == "" {
250							return nil, status.Errorf(codes.InvalidArgument, "title is required")
251						}
252						shortcut.Title = request.Shortcut.GetTitle()
253					} else if field == "filter" {
254						if err := s.validateFilter(ctx, request.Shortcut.GetFilter()); err != nil {
255							return nil, status.Errorf(codes.InvalidArgument, "invalid filter: %v", err)
256						}
257						shortcut.Filter = request.Shortcut.GetFilter()
258					}
259				}
260			}
261			newShortcuts = append(newShortcuts, shortcut)
262		}
263	
264		if foundShortcut == nil {
265			return nil, status.Errorf(codes.NotFound, "shortcut not found")
266		}
267	
268		shortcutsUserSetting.Shortcuts = newShortcuts
269		userSetting.Value = &storepb.UserSetting_Shortcuts{
270			Shortcuts: shortcutsUserSetting,
271		}
272		_, err = s.Store.UpsertUserSetting(ctx, userSetting)
273		if err != nil {
274			return nil, err
275		}
276	
277		return &v1pb.Shortcut{
278			Name:   constructShortcutName(user.Username, foundShortcut.GetId()),
279			Title:  foundShortcut.GetTitle(),
280			Filter: foundShortcut.GetFilter(),
281		}, nil
282	}
283	
284	func (s *APIV1Service) DeleteShortcut(ctx context.Context, request *v1pb.DeleteShortcutRequest) (*emptypb.Empty, error) {
285		user, shortcutID, err := s.extractUserAndShortcutIDFromName(ctx, request.Name)
286		if err != nil {
287			return nil, status.Errorf(codes.InvalidArgument, "invalid shortcut name: %v", err)
288		}
289		userID := user.ID
290	
291		currentUser, err := s.fetchCurrentUser(ctx)
292		if err != nil {
293			return nil, status.Errorf(codes.Internal, "failed to get current user: %v", err)
294		}
295		if currentUser == nil || currentUser.ID != userID {
296			return nil, status.Errorf(codes.PermissionDenied, "permission denied")
297		}
298	
299		userSetting, err := s.Store.GetUserSetting(ctx, &store.FindUserSetting{
300			UserID: &userID,
301			Key:    storepb.UserSetting_SHORTCUTS,
302		})
303		if err != nil {
304			return nil, err
305		}
306		if userSetting == nil {
307			return nil, status.Errorf(codes.NotFound, "shortcut not found")
